/* =========================================================
   FILE: apply_diary_texture.js
========================================================= */

const fs = require('fs');
const path = require('path');

const publicDir = path.join(__dirname, 'public');
const files = fs.readdirSync(publicDir).filter(f => f.endsWith('.html'));
const timestamp = Date.now();

files.forEach(file => {
    const p = path.join(publicDir, file);
    let content = fs.readFileSync(p, 'utf8');

    // Remove the previously injected dynamic theme script
    content = content.replace(/<script>\s*\/\/\s*실시간 시간대별 배경 테마 적용[\s\S]*?<\/script>/, '');

    // Cache busting CSS
    content = content.replace(/href="\/style\.css(\?[^"]*)?"/g, `href="/style.css?v=${timestamp}"`);

    fs.writeFileSync(p, content, 'utf8');
});

console.log('Diary texture applied and dynamic theme removed.');


/* =========================================================
   FILE: apply_dynamic_theme_again.js
========================================================= */

const fs = require('fs');
const path = require('path');

const publicDir = path.join(__dirname, 'public');
const files = fs.readdirSync(publicDir).filter(f => f.endsWith('.html'));

const themeScript = `
<script>
// 실시간 시간대별 배경 테마 적용 (아침, 저녁, 밤)
function applyDynamicTheme() {
    const hour = new Date().getHours();
    const bd = document.body;
    bd.classList.remove('theme-morning', 'theme-evening', 'theme-night');
    if (hour >= 6 && hour < 17) {
        bd.classList.add('theme-morning'); // 낮/아침: 밝은 하늘
    } else if (hour >= 17 && hour < 20) {
        bd.classList.add('theme-evening'); // 저녁: 노을
    } else {
        bd.classList.add('theme-night');   // 밤: 다크블루
    }
}
applyDynamicTheme();
setInterval(applyDynamicTheme, 60000); // 1분 주기로 테마 확인
</script>
`;

const timestamp = Date.now();

files.forEach(file => {
    const p = path.join(publicDir, file);
    let content = fs.readFileSync(p, 'utf8');

    // 1. 기존에 잘못 들어간 테마 스크립트가 있다면 지우기 (방어적 코드)
    content = content.replace(/<script>\s*\/\/\s*실시간 시간대별 배경 테마 적용[\s\S]*?<\/script>/, '');

    // 2. </body> 바로 앞에 스크립트 추가
    content = content.replace(/<\/body>/i, themeScript + '\n</body>');

    // 3. CSS 캐시 파괴 처리
    content = content.replace(/href="\/style\.css(\?[^"]*)?"/g, `href="/style.css?v=${timestamp}"`);

    fs.writeFileSync(p, content, 'utf8');
});

console.log('Dynamic time-based theme injected and cache busted successfully.');


/* =========================================================
   FILE: apply_particle_theme.js
========================================================= */

const fs = require('fs');
const path = require('path');

const publicDir = path.join(__dirname, 'public');
const files = fs.readdirSync(publicDir).filter(f => f.endsWith('.html'));
const timestamp = Date.now();

const advancedThemeScript = `
<!-- 시간대별 고급 파티클 테마 및 글로우 효과 -->
<canvas id="themeCanvas" style="position:fixed; top:0; left:0; width:100%; height:100%; z-index:-1; pointer-events:none;"></canvas>
<script>
(function() {
    function applyBodyTheme(hour) {
        document.body.classList.remove('theme-morning', 'theme-evening', 'theme-night');
        if (hour >= 6 && hour < 17) {
            document.body.classList.add('theme-morning');
        } else if (hour >= 17 && hour < 20) {
            document.body.classList.add('theme-evening');
        } else {
            document.body.classList.add('theme-night');
        }
    }

    const canvas = document.getElementById('themeCanvas');
    const ctx = canvas.getContext('2d');
    let width, height;
    let particles = [];
    let currentHour = new Date().getHours();
    
    function resize() {
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
    }
    window.addEventListener('resize', resize);
    resize();

    function initParticles() {
        particles = [];
        let count = 0;
        let isNight = currentHour >= 20 || currentHour < 6;
        let isEve = currentHour >= 17 && currentHour < 20;
        let isMorning = currentHour >= 6 && currentHour < 17;

        if (isMorning) count = 50; // 아침: 부유하는 먼지/햇살
        else if (isEve) count = 40; // 저녁: 따뜻한 주황빛 입자
        else count = 120; // 밤: 별처럼 많은 수

        for (let i = 0; i < count; i++) {
            particles.push(createParticle(isNight, isEve, isMorning));
        }
    }

    function createParticle(isNight, isEve, isMorning) {
        let size, speedX, speedY, color, twinkleSpeed;
        if (isMorning) {
            size = Math.random() * 2 + 1;
            speedX = (Math.random() - 0.5) * 0.3;
            speedY = Math.random() * -0.5 - 0.2; // 부드럽게 위로 상승
            color = \`rgba(255, 255, 255, \${Math.random() * 0.4 + 0.1})\`;
            twinkleSpeed = 0;
        } else if (isEve) {
            size = Math.random() * 3 + 1;
            speedX = (Math.random() - 0.5) * 0.8;
            speedY = (Math.random() - 0.5) * 0.8; // 부드럽게 사방 확산
            color = \`rgba(255, 200, \${Math.floor(Math.random() * 100 + 50)}, \${Math.random() * 0.6 + 0.2})\`;
            twinkleSpeed = 0;
        } else {
            size = Math.random() * 1.5;
            speedX = (Math.random() - 0.5) * 0.1;
            speedY = (Math.random() - 0.5) * 0.1;
            color = \`rgba(255, 255, 255, \${Math.random() * 0.8 + 0.2})\`;
            twinkleSpeed = Math.random() * 0.02 + 0.005;
        }
        return { x: Math.random() * width, y: Math.random() * height, size, speedX, speedY, color, twinkleSpeed, alpha: isNight ? Math.random() : 1, alphaDir: 1 };
    }

    function drawParticles() {
        ctx.clearRect(0, 0, width, height);
        let isNight = currentHour >= 20 || currentHour < 6;
        
        particles.forEach(p => {
            if (isNight) {
                p.alpha += p.twinkleSpeed * p.alphaDir;
                if (p.alpha > 1) { p.alpha = 1; p.alphaDir = -1; }
                if (p.alpha < 0.1) { p.alpha = 0.1; p.alphaDir = 1; }
            }
            
            p.x += p.speedX;
            p.y += p.speedY;
            
            if (p.x < -10) p.x = width + 10;
            if (p.x > width + 10) p.x = -10;
            if (p.y < -10) p.y = height + 10;
            if (p.y > height + 10) p.y = -10;
            
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            if (isNight) {
                // RGBA 파싱하여 alpha 값 교체
                const cArr = p.color.split(',');
                ctx.fillStyle = \`\${cArr[0]},\${cArr[1]},\${cArr[2]},\${p.alpha})\`;
            } else {
                ctx.fillStyle = p.color;
                // 글로우 효과 (아침/저녁)
                ctx.shadowBlur = p.size * 3;
                ctx.shadowColor = p.color;
            }
            ctx.fill();
        });
        requestAnimationFrame(drawParticles);
    }

    applyBodyTheme(currentHour);
    initParticles();
    drawParticles();

    // 1분마다 테마 업데이트 체크
    setInterval(() => {
        let newHour = new Date().getHours();
        if (newHour !== currentHour) {
            currentHour = newHour;
            applyBodyTheme(currentHour);
            initParticles();
        }
    }, 60000);
})();
</script>
`;

files.forEach(file => {
    const p = path.join(publicDir, file);
    let content = fs.readFileSync(p, 'utf8');

    // Remove old base theme script
    content = content.replace(/<script>\s*\/\/\s*실시간 시간대별 배경 테마 적용[\s\S]*?<\/script>/g, '');
    
    // Remove if advanced script already exists (idempotency)
    content = content.replace(/<!-- 시간대별 고급 파티클 테마 및 글로우 효과 -->[\s\S]*?<\/script>/, '');

    // Insert advanced themed script before </body>
    content = content.replace(/<\/body>/i, advancedThemeScript + '\n</body>');

    // Apply strict cache busting to style.css
    content = content.replace(/href="\/style\.css(\?[^"]*)?"/g, `href="/style.css?v=${timestamp}"`);

    fs.writeFileSync(p, content, 'utf8');
});

console.log('Advanced particle themes injected and cache busted successfully.');


