const fs = require('fs');
const path = require('path');

const publicDir = path.join(__dirname, 'public');
const files = fs.readdirSync(publicDir).filter(f => f.endsWith('.html'));

files.forEach(file => {
    const p = path.join(publicDir, file);
    let content = fs.readFileSync(p, 'utf8');

    // Change 20000 to 3000
    content = content.replace(/20000\);/g, '3000);');
    
    // Add beforeunload beacon to delete session immediately on tab close
    // Because sendBeacon is fast and doesn't block
    if (!content.includes('sendBeacon')) {
        content = content.replace(/window\.logout = function/g, `
    window.addEventListener('beforeunload', () => {
        const u = sessionStorage.getItem('loginUser');
        if (u) {
            navigator.sendBeacon('/api/logout', JSON.stringify({username: u}));
        }
    });

    window.logout = function`);
    }

    fs.writeFileSync(p, content, 'utf8');
});

const appFile = path.join(__dirname, 'app.js');
let appContent = fs.readFileSync(appFile, 'utf8');
appContent = appContent.replace(/< 60000/g, '< 8000'); // Change 60s to 8s
fs.writeFileSync(appFile, appContent, 'utf8');

console.log('Timeout reduced and beacon added.');


