const fs = require('fs');
const files = ['public/board.html', 'public/write.html', 'public/view.html', 'public/edit.html'];
for (const file of files) {
  let content = fs.readFileSync(file, 'utf8');
  if (file.includes('board') || file.includes('write')) {
    content = content.replace(/\/\* 1\. 상단 메뉴바 스타일 \*\/[\s\S]*?(?=\/\* \[핵심 수정\])/g, '');
  } else if (file.includes('view')) {
    content = content.replace(/\/\* 1\. 상단 메뉴바 스타일 \*\/[\s\S]*?(?=\/\* 2\. 상세보기)/g, '');
  } else if (file.includes('edit')) {
    content = content.replace(/\.navbar\s*\{[\s\S]*?\.nav-logo\s*\{[\s\S]*?cursor:\s*pointer;\s*\}/g, '');
  }
  fs.writeFileSync(file, content, 'utf8');
}
