/* pokedex-app.js — Pokédex grid, filter, and modal logic */

document.addEventListener('DOMContentLoaded', () => {
    const { ANIMAL_DEFS, PET_SVGS } = window.POKEDEX_DATA;
    const grid = document.getElementById('pokedexGrid');
    const filterBtns = document.querySelectorAll('.filter-btn');
    const statsDiscovered = document.getElementById('discoveredCount');
    const statsMaxed = document.getElementById('maxedCount');
    const modal = document.getElementById('dexModal');
    const evoTimeline = document.getElementById('evoTimeline');

    const username = sessionStorage.getItem('loginUser') || localStorage.getItem('loginUser') || '';

    function renderGrid(completed, currentType, currentLevel) {
        grid.innerHTML = '';
        const animalKeys = Object.keys(ANIMAL_DEFS);
        let discovered = 0, maxed = 0;

        animalKeys.forEach((key, idx) => {
            const def = ANIMAL_DEFS[key];
            const isCompleted = completed.includes(key);
            const isCurrent = key === currentType;
            const isKnown = isCompleted || isCurrent;

            const card = document.createElement('div');
            card.className = 'dex-card';
            card.dataset.key = key;
            card.dataset.completed = isCompleted;
            card.dataset.discovered = isKnown;
            if (isCompleted) card.classList.add('completed');
            if (!isKnown) card.classList.add('undiscovered');

            // Number badge
            card.innerHTML = `<span class="dex-card-number">#${String(idx+1).padStart(3,'0')}</span>`;

            // SVG
            const svgIdx = isCompleted ? 3 : Math.min((currentLevel || 1) - 1, 3);
            const svgDiv = document.createElement('div');
            svgDiv.className = 'dex-card-svg';
            svgDiv.innerHTML = isKnown ? PET_SVGS[key][svgIdx] : PET_SVGS[key][0];
            card.appendChild(svgDiv);

            // Name
            const nameEl = document.createElement('div');
            nameEl.className = 'dex-card-name';
            nameEl.textContent = isKnown ? def.name : '???';
            card.appendChild(nameEl);

            // Icon badge
            const typeEl = document.createElement('div');
            typeEl.className = 'dex-card-type';
            typeEl.textContent = isKnown ? def.icon : '❓';
            card.appendChild(typeEl);

            // Level dots
            const dots = document.createElement('div');
            dots.className = 'dex-card-levels';
            for (let i = 1; i <= 4; i++) {
                const dot = document.createElement('div');
                dot.className = 'level-dot';
                const maxDot = isCompleted ? 4 : (isCurrent ? currentLevel : 0);
                if (i <= maxDot) dot.classList.add('active');
                dots.appendChild(dot);
            }
            card.appendChild(dots);

            card.addEventListener('click', () => openModal(key, def, isCompleted, isCurrent ? (currentLevel || 1) : (isCompleted ? 4 : 0)));
            grid.appendChild(card);

            if (isKnown) discovered++;
            if (isCompleted) maxed++;
        });

        statsDiscovered.textContent = discovered;
        statsMaxed.textContent = maxed;
    }

    // Try fetch; fallback to showing all as undiscovered if username missing
    if (username) {
        fetch(`/api/pet?username=${encodeURIComponent(username)}`)
            .then(r => r.json())
            .then(data => {
                const pet = data.pet || {};
                const completed = (pet.completed_types || '').split(',').filter(Boolean);
                renderGrid(completed, pet.pet_type, pet.level || 1);
            })
            .catch(() => renderGrid([], '', 1));
    } else {
        renderGrid([], '', 1);
    }

    // Filter
    filterBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            filterBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            const f = btn.dataset.filter;
            document.querySelectorAll('.dex-card').forEach(card => {
                const comp = card.dataset.completed === 'true';
                const disc = card.dataset.discovered === 'true';
                if (f === 'all') card.style.display = '';
                else if (f === 'discovered') card.style.display = disc ? '' : 'none';
                else if (f === 'undiscovered') card.style.display = !disc ? '' : 'none';
                else if (f === 'completed') card.style.display = comp ? '' : 'none';
            });
        });
    });

    // Modal
    let currentModalKey = null;
    let currentModalLevel = 1;

    function openModal(key, def, isCompleted, level) {
        currentModalKey = key;
        currentModalLevel = level;
        const animalKeys = Object.keys(ANIMAL_DEFS);
        const idx = animalKeys.indexOf(key);
        const stageIdx = isCompleted ? 3 : Math.max(0, Math.min(level - 1, 3));
        const stage = def.stages[stageIdx];

        document.getElementById('modalNumber').textContent = `#${String(idx+1).padStart(3,'0')}`;
        document.getElementById('modalName').textContent = def.name;
        document.getElementById('modalSvg').innerHTML = PET_SVGS[key][stageIdx];
        document.getElementById('modalLevel').textContent = `Lv.${stageIdx + 1}`;
        document.getElementById('modalStage').textContent = stage.n;
        document.getElementById('modalMsg').textContent = `"${stage.msg}"`;
        document.getElementById('modalDesc').textContent = `${def.name}(${def.icon})의 ${stageIdx + 1}단계 모습이에요.`;

        // Build timeline
        evoTimeline.innerHTML = '';
        def.stages.forEach((s, i) => {
            const el = document.createElement('div');
            el.className = 'evo-stage' + (i === stageIdx ? ' active' : '') + (i > stageIdx && !isCompleted ? ' locked' : '');
            const svg = document.createElement('div');
            svg.className = 'evo-stage-svg';
            svg.innerHTML = PET_SVGS[key][i];
            const lbl = document.createElement('div');
            lbl.className = 'evo-stage-label';
            lbl.textContent = `Lv.${i+1}`;
            el.appendChild(svg);
            el.appendChild(lbl);
            el.addEventListener('click', () => {
                document.querySelectorAll('.evo-stage').forEach(e => e.classList.remove('active'));
                el.classList.add('active');
                document.getElementById('modalSvg').innerHTML = PET_SVGS[key][i];
                document.getElementById('modalLevel').textContent = `Lv.${i+1}`;
                document.getElementById('modalStage').textContent = s.n;
                document.getElementById('modalMsg').textContent = `"${s.msg}"`;
            });
            evoTimeline.appendChild(el);

            if (i < 3) {
                const arrow = document.createElement('div');
                arrow.className = 'evo-arrow';
                arrow.textContent = '▶';
                evoTimeline.appendChild(arrow);
            }
        });

        modal.classList.add('show');
    }

    window.closeModal = () => modal.classList.remove('show');

    // Close on backdrop click
    modal.addEventListener('click', e => { if (e.target === modal) closeModal(); });
});



